/* Tip Splitter — one calm, centered card.
   Class hooks: .field, .result, .result-row, .result-total, .message, .invalid */

:root {
  /* Colour */
  --bg: #f4f6f8;
  --card: #ffffff;
  --text: #1c2430;
  --muted: #5b6675;
  --line: #d6dce3;
  --accent: #2f6f8f;
  --accent-soft: #e6f0f5;
  --hint-bg: #fdf6e7;
  --hint-text: #6b4e12;
  --hint-line: #f0dcae;

  /* Scale */
  --space-1: 0.5rem;
  --space-2: 1rem;
  --space-3: 1.5rem;
  --space-4: 2rem;
  --radius: 12px;
  --tap: 3rem; /* 48px tap targets */

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #12161b;
    --card: #1b2128;
    --text: #e8edf2;
    --muted: #9aa6b4;
    --line: #313a45;
    --accent: #7fbad6;
    --accent-soft: #1f2d36;
    --hint-bg: #2a2416;
    --hint-text: #ecd69f;
    --hint-line: #4a3e22;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  padding: var(--space-2);
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  overflow-x: hidden;
}

/* The card */
main,
.card {
  width: 100%;
  max-width: 26rem;
  padding: var(--space-3);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.04), 0 8px 24px rgb(0 0 0 / 0.06);
}

h1 {
  margin: 0 0 var(--space-3);
  font-size: 1.5rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  line-height: 1.2;
}

form {
  margin: 0;
}

/* One label + its input */
.field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: var(--space-2);
}

.field label {
  font-size: 0.9375rem;
  font-weight: 550;
  color: var(--muted);
}

input {
  width: 100%;
  min-width: 0;
  min-height: var(--tap);
  padding: 0.625rem 0.875rem;
  font: inherit;
  font-size: 1.125rem; /* >= 16px so phones don't zoom on focus */
  font-variant-numeric: tabular-nums;
  color: var(--text);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) - 4px);
  transition: border-color 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
}

input:hover {
  border-color: var(--muted);
}

input:focus {
  outline: none;
}

input:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

/* A field with a problem: a soft highlight, not an alarm */
input.invalid,
.invalid input {
  border-color: var(--hint-line);
  background: var(--hint-bg);
}

input.invalid:focus-visible,
.invalid input:focus-visible {
  border-color: var(--hint-text);
  box-shadow: 0 0 0 3px var(--hint-line);
}

/* Friendly hint */
.message {
  margin: 0 0 var(--space-2);
  padding: 0.75rem var(--space-2);
  font-size: 0.9375rem;
  color: var(--hint-text);
  background: var(--hint-bg);
  border: 1px solid var(--hint-line);
  border-radius: calc(var(--radius) - 4px);
}

.message:empty,
[hidden] {
  display: none !important;
}

/* Result area */
.result {
  margin-top: var(--space-3);
  padding-top: var(--space-2);
  border-top: 1px solid var(--line);
}

.result-row,
.result-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--space-2);
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.result-row {
  padding: 0.25rem 0;
  color: var(--muted);
}

.result-row > :last-child {
  color: var(--text);
  font-weight: 550;
}

/* "Each person pays" — the answer, biggest and clearest */
.result-total {
  flex-wrap: wrap;
  margin-top: var(--space-2);
  padding: var(--space-2);
  background: var(--accent-soft);
  border-radius: calc(var(--radius) - 4px);
  font-weight: 600;
}

.result-total > :last-child {
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--accent);
}

/* Laptop: a touch more air */
@media (min-width: 40rem) {
  main,
  .card {
    padding: var(--space-4);
  }

  h1 {
    font-size: 1.75rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

